\title{LMG Index: A Robust and Efficient Learned Index Framework for Multi-Dimensional Performance Balance}




\author{Yuzhen Chen \textsuperscript{1}\and
        Bin Yao \textsuperscript{1}
}



\institute{
        \Letter Bin Yao \at
        \email{yaobin@cs.sjtu.edu.cn}   
        \and
        Yuzhen Chen \at
